WITH unpacked AS (SELECT id, service, log_ts, FROM_JSON(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').retries AS retry_count, COALESCE(context['region'], 'unknown') AS region_or_default, ARRAY_CONTAINS(MAP_KEYS(context), 'region') AS has_region, FROM_JSON(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').duration AS duration_sec, SIZE(context) AS num_context FROM app_logs WHERE service IN ('search', 'auth', 'checkout')) SELECT id, service, retry_count, has_region, num_context, MIN(retry_count) OVER w_part AS running_min_retry_count, AVG(retry_count) OVER w_part AS running_avg_retry_count, MAX(retry_count) OVER w_part AS running_max_retry_count FROM unpacked WINDOW w_part AS (PARTITION BY service ORDER BY log_ts, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)
